<?php
/** Proof — rules, snooze and auto-close (spec "Proof", 3–4): pending_until in the past → open via auto with pending_elapsed; solved 5 days ago → closed and its link dated; auto_close_days = 0 → never; the seeded two fire through the rules step; days_since with setting:auto_close_days; a problem solved → its children solved with the note; a missing status → skipped with the sentence; a throwing action → error and the next rule runs; Would match N = applied + skipped. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $owner = as_member(1);
echo "1. Snooze and auto-close (the worker's own steps)\n";
$ts = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE snoozed', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
act($marco, '/tickets/assign.php', ['ticket' => $ts, 'assignee' => 'me']);
act($marco, '/tickets/transition.php', ['ticket' => $ts, 'status' => 'pending', 'pending_until' => (new DateTimeImmutable('+1 day'))->format('Y-m-d\TH:i')]);
$since = last_activity_id();
$r = worker(['snooze'], at('+2 days'));
$tr = array_values(array_filter(activity('ticket.transition', $since), fn ($x) => (int) $x['ticket_id'] === $ts));
ok($r['snooze'] >= 1 && ticket_status($ts) === 'open' && count($tr) === 1 && json_decode($tr[0]['after'], true)['via'] === 'auto' && ticket_row($ts)['pending_until'] === null, 'pending_until passed: open via auto, the wake-up cleared');
ok(count(q("SELECT 1 FROM notifications WHERE ticket_id = :t AND kind = 'pending_elapsed' AND member_id = 27", ['t' => $ts])) === 1, 'pending_elapsed queued for the assignee');
$tc = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE to auto-close', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
act($marco, '/tickets/transition.php', ['ticket' => $tc, 'status' => 'open']);
act($marco, '/tickets/transition.php', ['ticket' => $tc, 'status' => 'solved', 'resolution_code' => 'resolved']);
q("UPDATE tickets SET solved_at = now() - interval '5 days' WHERE id = :t", ['t' => $tc]);
q('UPDATE app_settings SET auto_close_days = 0 WHERE id = 1');
worker(['auto_close']);
ok(ticket_status($tc) === 'solved', 'auto_close_days = 0: never');
q('UPDATE app_settings SET auto_close_days = 4 WHERE id = 1');
$since = last_activity_id();
$r = worker(['auto_close']);
ok($r['auto_close'] >= 1 && ticket_status($tc) === 'closed' && one('SELECT expires_at FROM ticket_links_secure WHERE ticket_id = :t AND rotated_at IS NULL', ['t' => $tc]) !== null, 'solved 5 days ago: closed, its secure link dated');
ok(json_decode(array_values(array_filter(activity('ticket.transition', $since), fn ($x) => (int) $x['ticket_id'] === $tc))[0]['after'], true)['via'] === 'auto', 'via auto');
echo "2. The seeded rules fire through the rules step\n";
$tc2 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE closed by the rule', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
act($marco, '/tickets/transition.php', ['ticket' => $tc2, 'status' => 'open']);
act($marco, '/tickets/transition.php', ['ticket' => $tc2, 'status' => 'solved', 'resolution_code' => 'resolved']);
q("UPDATE tickets SET solved_at = now() - interval '5 days' WHERE id = :t", ['t' => $tc2]);
$ts2 = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE snoozed for the rule', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
act($marco, '/tickets/transition.php', ['ticket' => $ts2, 'status' => 'pending', 'pending_until' => (new DateTimeImmutable('+1 hour'))->format('Y-m-d\TH:i')]);
$closeRule = (int) one("SELECT id FROM automation_rules WHERE name = 'Close solved tickets after the window'");
$snoozeRule = (int) one("SELECT id FROM automation_rules WHERE name = 'Reopen when the snooze passes'");
$since = last_activity_id();
$r = worker(['rules'], at('+2 hours'));
ok(ticket_status($tc2) === 'closed' && ticket_status($ts2) === 'open', 'the two seeded rules: the solved one closed, the snoozed one reopened');
$fires = activity('rule.fire', $since);
ok(count(array_filter($fires, fn ($x) => (int) $x['ticket_id'] === $tc2 && json_decode($x['after'], true)['rule_id'] === $closeRule && json_decode($x['after'], true)['outcome'] === 'applied')) === 1 && count(rule_runs_of($closeRule)) >= 1 && (int) one('SELECT run_count FROM automation_rules WHERE id = :r', ['r' => $closeRule]) >= 1, 'rule.fire and a rule_runs row for the close rule; run_count up');
ok(json_decode(array_values(array_filter(activity('ticket.transition', $since), fn ($x) => (int) $x['ticket_id'] === $tc2))[0]['after'], true)['via'] === 'rule', 'the move via rule');
ok(($r['rules'][$closeRule]['applied'] ?? 0) >= 1 && ($r['rules'][$snoozeRule]['applied'] ?? 0) >= 1, 'the report counts per rule');
echo "3. A problem solves its incidents\n";
$pid = type_id('problem');
$prob = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE the problem', 'body' => 'x', 'queue' => $W['it'], 'type' => $pid])[1]['record_id'];
$kids = [];
for ($i = 1; $i <= 3; $i++) { $kids[] = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE incident ' . $i, 'body' => 'x', 'queue' => $W['it']])[1]['record_id']; }
foreach ($kids as $k) { act($marco, '/tickets/link.php', ['ticket' => $prob, 'other_ticket' => $k, 'kind' => 'parent_child']); }
act($marco, '/tickets/transition.php', ['ticket' => $prob, 'status' => 'open']);
act($marco, '/tickets/transition.php', ['ticket' => $prob, 'status' => 'solved', 'resolution_code' => 'resolved']);
[$c, $b] = act($owner, '/settings/automation/save.php', ['name' => 'SMOKE problem solves incidents', 'kind' => 'time_based', 'conditions' => json_encode(['all' => [['field' => 'type_id', 'op' => 'eq', 'value' => $pid], ['field' => 'status_category', 'op' => 'eq', 'value' => 'solved']]]), 'actions' => json_encode([['link_children' => 'solve']])]);
$pr = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $pr > 0, 'the rule saved through the handler');
[$c, $d] = screen($owner, '/settings/automation/' . $pr . '/edit');
$preview = $d['preview'] ?? -1;
[$c, $b] = act($owner, '/settings/automation/run.php', ['rule' => $pr]);
ok($c === 200 && ($b['applied'] ?? 0) === 1 && str_contains((string) $b['did'], "Ran 'SMOKE problem solves incidents' on"), 'Run now: applied to the problem (' . $c . ' ' . json_encode($b) . ')');
ok(count(array_filter($kids, fn ($k) => ticket_status($k) === 'solved' && ticket_row($k)['resolution_code'] === 'resolved')) === 3, 'its three children solved with resolved');
ok((int) one("SELECT count(*) FROM messages WHERE ticket_id = ANY(CAST(:k AS bigint[])) AND kind = 'internal_note' AND body_text LIKE 'Solved with the problem %'", ['k' => '{' . implode(',', $kids) . '}']) === 3, 'each child got the note naming the parent');
ok($preview === ($b['applied'] + $b['skipped']), '"Would match N" (' . $preview . ') equals applied + skipped (' . ($b['applied'] + $b['skipped']) . ')');
[$c, $b] = act($owner, '/settings/automation/run.php', ['rule' => $pr]);
ok(($b['applied'] ?? 1) === 0 && ($b['skipped'] ?? 0) >= 1, 'run again: the problem is skipped (no open children)');
echo "4. A missing status, a throwing action, and the pass goes on\n";
$bad = plant_rule('SMOKE missing status', 'time_based', ['all' => [['field' => 'status_category', 'op' => 'eq', 'value' => 'new']]], [['transition' => 'parked']], null, 5);
$boom = plant_rule('SMOKE boom', 'time_based', ['all' => [['field' => 'status_category', 'op' => 'eq', 'value' => 'new']]], [['set' => ['due_at' => 'not-a-date']]], null, 6);
$after = plant_rule('SMOKE after the boom', 'time_based', ['all' => [['field' => 'status_category', 'op' => 'eq', 'value' => 'new'], ['field' => 'subject_contains', 'op' => 'contains', 'value' => 'incident 1']]], [['add_tags' => ['after-boom']]], null, 7);
act($marco, '/tickets/transition.php', ['ticket' => $kids[0], 'status' => 'open']);
act($marco, '/tickets/reopen.php', ['ticket' => $kids[0]]);
$tn = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE a new one incident 1', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
$r = worker(['rules']);
$badRuns = rule_runs_of($bad);
ok(count($badRuns) >= 1 && $badRuns[0]['outcome'] === 'skipped' && str_contains((string) $badRuns[0]['detail'], "No status 'parked'."), "a missing status: skipped with \"No status 'parked'.\"");
$boomRuns = rule_runs_of($boom);
ok(count($boomRuns) >= 1 && $boomRuns[0]['outcome'] === 'error' && ($r['rules'][$boom]['error'] ?? 0) >= 1, 'a throwing action: error, counted');
$afterRuns = rule_runs_of($after);
ok(count($afterRuns) >= 1 && $afterRuns[0]['outcome'] === 'applied' && in_array('after-boom', pg_text_array((string) one('SELECT tags FROM mcp_tickets WHERE ticket_id = :t', ['t' => $tn])), true), 'the next rule still ran and tagged the ticket');
$r2 = worker(['rules']);
ok(($r2['rules'][$after]['applied'] ?? 1) === 0 && ($r2['rules'][$after]['skipped'] ?? 0) >= 1, 'a second pass: the tag rule skips (nothing to change)');
q('UPDATE automation_rules SET active = false WHERE id IN (:a, :b, :c)', ['a' => $bad, 'b' => $boom, 'c' => $after]);
echo "5. days_since with a setting\n";
$sr = plant_rule('SMOKE old solved note', 'time_based', ['all' => [['field' => 'status_category', 'op' => 'eq', 'value' => 'solved'], ['field' => 'days_since', 'args' => 'solved_at', 'op' => 'gte', 'value' => 'setting:auto_close_days']]], [['note' => 'Still solved after the window: {{ticket.number}}']], null, 50);
$old = (int) act($marco, '/tickets/save.php', ['subject' => 'SMOKE old solved', 'body' => 'x', 'queue' => $W['it'], 'requester' => $W['jo']])[1]['record_id'];
act($marco, '/tickets/transition.php', ['ticket' => $old, 'status' => 'open']);
act($marco, '/tickets/transition.php', ['ticket' => $old, 'status' => 'solved', 'resolution_code' => 'resolved']);
q("UPDATE tickets SET solved_at = now() - interval '5 days' WHERE id = :t", ['t' => $old]);
q('UPDATE automation_rules SET active = false WHERE id = :r', ['r' => $closeRule]);
worker(['rules']);
ok((int) one("SELECT count(*) FROM messages WHERE ticket_id = :t AND kind = 'internal_note' AND body_text = :b", ['t' => $old, 'b' => 'Still solved after the window: ' . ticket_row($old)['number']]) === 1, 'days_since solved_at ≥ setting:auto_close_days (4): the note with the placeholder filled');
q('UPDATE automation_rules SET active = true WHERE id = :r', ['r' => $closeRule]);
q('UPDATE automation_rules SET active = false WHERE id = :r', ['r' => $sr]);
finish();
